{
  "scene": "Fixed-camera cartoon-style 3D animation of the word 'MADPENCIL' made from shiny silver foil balloon letters on a soft purple background.",
  "style": "Classic slapstick cartoon energy, exaggerated squash-and-stretch physics, rubber-hose motion, comedic timing, polished 3D animation, glossy reflections, playful physical comedy.",
  "camera": {
    "movement": "locked",
    "framing": "centered wide shot",
    "background": "soft purple gradient"
  },
  "objects": [
    {
      "type": "balloon_letters",
      "text": "MADPENCIL",
      "material": "shiny silver foil balloon",
      "behavior": "gentle wobble and elastic jiggle"
    },
    {
      "type": "pencil_character",
      "appearance": "bright yellow pencil with pink eraser and sharpened graphite tip",
      "behavior": "hyperactive bouncing cartoon physics"
    }
  ],
  "timeline": [
    {
      "time": "0-2s",
      "action": "The pencil drops vertically into frame, slams onto the ground with exaggerated squash-and-stretch, then rebounds upward. Balloon letters jiggle from the impact shockwave. Small dust puffs and motion blur enhance the comedic impact."
    },
    {
      "time": "2-5s",
      "action": "The pencil ricochets wildly across the word, bouncing between letters with chaotic elastic physics. Each collision makes nearby balloon letters wobble and squeak. The pencil spins midair with exaggerated cartoon motion."
    },
    {
      "time": "5-7s",
      "action": "The pencil begins targeting the balloon letter 'I'. It circles around it playfully, bouncing off nearby letters while building anticipation. The 'I' balloon wiggles nervously."
    },
    {
      "time": "7-9s",
      "action": "The pencil launches high into the air in dramatic anticipation, freezes briefly at the peak, then dives downward tip-first toward the balloon 'I' with extreme squash-and-stretch and dynamic smear-frame motion."
    },
    {
      "time": "9-10s",
      "action": "The pencil lands directly onto the balloon 'I' with a huge comedic POP. The balloon bursts into shiny silver fragments and escaping air puffs. Nearby letters shake violently. The pencil remains stuck upright where the 'I' used to be, wobbling victoriously as balloon scraps float downward."
    }
  ],
  "lighting": {
    "type": "soft cinematic studio lighting",
    "details": "glossy highlights and smooth reflections on balloon surfaces"
  },
  "animation_notes": [
    "Maintain fixed camera throughout",
    "Use exaggerated cartoon timing and anticipation",
    "Apply elastic physics to all balloon letters",
    "Add subtle motion blur during fast actions",
    "Keep animation energetic, playful, and polished"
  ]
}

