  "scene": "Animación 3D estilo caricatura con cámara fija de la palabra 'MADPENCIL' hecha de letras de globo de papel aluminio plateado brillante sobre un fondo púrpura suave.",
  "style": "Energía clásica de caricatura slapstick, física exagerada de squash-and-stretch, movimiento de manguera de goma, tiempo cómico, animación 3D pulida, reflejos brillantes, comedia física juguetona.",
  "camera": {
    "movement": "locked",
    "framing": "centered wide shot",
    "background": "soft purple gradient"
  },
  "objects": [
    {
      "type": "balloon_letters",
      "text": "MADPENCIL",
      "material": "shiny silver foil balloon",
      "behavior": "gentle wobble and elastic jiggle"
    },
    {
      "type": "pencil_character",
      "appearance": "bright yellow pencil with pink eraser and sharpened graphite tip",
      "behavior": "hyperactive bouncing cartoon physics"
    }
  ],
  "timeline": [
    {
      "time": "0-2s",
      "action": "El lápiz cae verticalmente en el encuadre, golpea el suelo con un squash-and-stretch exagerado, luego rebota hacia arriba. Las letras de globo se tambalean por la onda de choque del impacto. Pequeñas nubes de polvo y desenfoque de movimiento mejoran el impacto cómico."
    },
    {
      "time": "2-5s",
      "action": "El lápiz rebota salvajemente a través de la palabra, rebotando entre las letras con física elástica caótica. Cada colisión hace que las letras de globo cercanas se tambaleen y chirríen. El lápiz gira en el aire con un movimiento de caricatura exagerado."
    },
    {
      "time": "5-7s",
      "action": "El lápiz comienza a apuntar a la letra de globo 'I'. Da vueltas a su alrededor juguetonamente, rebotando en letras cercanas mientras crea anticipación. El globo 'I' se agita nerviosamente."
    },
    {
      "time": "7-9s",
      "action": "El lápiz se lanza alto en el aire en una anticipación dramática, se congela brevemente en el pico, luego se lanza hacia abajo con la punta primero hacia el globo 'I' con un squash-and-stretch extremo y un movimiento de smear-frame dinámico."
    },
    {
      "time": "9-10s",
      "action": "El lápiz aterriza directamente sobre el globo 'I' con un gran POP cómico. El globo estalla en fragmentos plateados brillantes y puffs de aire escapando. Las letras cercanas tiemblan violentamente. El lápiz permanece clavado donde solía estar la 'I', tambaleándose victoriosamente mientras los restos del globo flotan hacia abajo."
    }
  ],
  "lighting": {
    "type": "soft cinematic studio lighting",
    "details": "glossy highlights and smooth reflections on balloon surfaces"
  },
  "animation_notes": [
    "Maintain fixed camera throughout",
    "Use exaggerated cartoon timing and anticipation",
    "Apply elastic physics to all balloon letters",
    "Add subtle motion blur during fast actions",
    "Keep animation energetic, playful, and polished"
  ]
}

